def _check_lexbfs_bruteforce(graph, order):
    """O(n^4) reference check, kept for cross-validation in tests."""
    n = len(order)
    adj = graph
    for a in range(n):
        va = order[a]
        for b in range(a + 1, n):
            vb = order[b]
            if adj[va][vb]:
                continue
            for c in range(b + 1, n):
                vc = order[c]
                if not adj[va][vc]:
                    continue
                found = False
                for d in range(a):
                    vd = order[d]
                    if adj[vd][vb] and not adj[vd][vc]:
